async def ingest_transaction(tx_id, payload, cache, db):
    lock_acquired = await cache.set(f'lock:tx:{tx_id}', '1', ex=600, nx=True)
    if not lock_acquired:
        return {'status': 'duplicate_ignored'}
    try:
        return await db.insert_once(tx_id, payload)
    except UniqueViolation:
        return {'status': 'already_processed'}
